    // 保存设置
    saveSettings() {
      this.$refs.settingsForm.validate(valid => {
        if (valid) {
          this.loading = true;

          // 模拟保存到API
          setTimeout(() => {
            this.loading = false;
            this.$message({
              type: 'success',
              message: '设置已保存'
            });
          }, 800);
        } else {
          return false;
        }
      });
    },
    // 重置设置
    resetSettings() {
      this.$confirm('确定要重置所有设置吗？这将恢复到初始值。', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.loadSettings();
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消重置'
        });
      });
    },
    // 立即备份
    handleBackupNow() {
      this.loading = true;

      // 模拟备份操作
      setTimeout(() => {
        this.loading = false;

        // 新增备份记录
        const now = new Date();
        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const day = String(now.getDate()).padStart(2, '0');
        const hours = String(now.getHours()).padStart(2, '0');
        const minutes = String(now.getMinutes()).padStart(2, '0');
        const seconds = String(now.getSeconds()).padStart(2, '0');
        const filename = `backup_${year}${month}${day}_${hours}${minutes}${seconds}.zip`;
        this.backupHistory.unshift({
          id: this.backupHistory.length + 1,
          filename,
          size: '25.6 MB',
          createTime: `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`,
          status: 'success'
        });
        this.$message({
          type: 'success',
          message: '备份成功'
        });
      }, 2000);
    },
    // 显示备份历史
    showBackupHistory() {
      this.backupHistoryVisible = true;
    },
    // 下载备份
    downloadBackup(backup) {
      this.$message({
        type: 'success',
        message: `开始下载：${backup.filename}`
      });
    },
    // 删除备份
    deleteBackup(backup) {
      this.$confirm(`确定要删除备份：${backup.filename}吗？`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        // 模拟删除备份
        this.backupHistory = this.backupHistory.filter(item => item.id !== backup.id);
        this.$message({
          type: 'success',
          message: '备份已删除'
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消删除'
        });
      });
    },
    // 测试邮件连接
    testEmailConnection() {
      if (!this.settings.smtpServer || !this.settings.smtpUsername || !this.settings.smtpPassword) {
        this.$message.error('请先完成SMTP设置');
        return;
      }
      this.loading = true;

      // 模拟测试邮件连接
      setTimeout(() => {
        this.loading = false;
        this.$message({
          type: 'success',
          message: '邮件连接测试成功'
        });
      }, 1500);
    },
    // 刷新系统状态信息
    refreshSystemStatus() {
      this.loading = true;
      this.$api.systemApi.getDashboardStatus().then(res => {
        if (res && res.data && res.status === 200) {
          this.systemStatus = res.data;
          this.$message({
            type: 'success',
            message: '系统状态已刷新'
          });
        } else {
          this.$message.error('获取系统状态失败：' + (res.msg || '未知错误'));
        }
      }).catch(err => {
        this.$message.error('获取系统状态失败：' + (err.message || '未知错误'));
      }).finally(() => {
        this.loading = false;
      });
    },
    // 格式化内存显示
    formatMemory(memory) {
      if (!memory) return '0 MB';
      if (memory < 1024) {
        return memory.toFixed(0) + ' MB';
      } else {
        return (memory / 1024).toFixed(2) + ' GB';
      }
    }
